import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

import { drizzle } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import { z } from 'zod';

import type pg from 'pg';

/** Absolute path of the forward-only SQL migrations (generated by `pnpm db:generate`, then reviewed). */
export const MIGRATIONS_DIR = fileURLToPath(new URL('../migrations/', import.meta.url));

/** Where applied migrations are recorded (same as `src/drizzle.config.ts`, used by `pnpm db:migrate`). */
export const MIGRATIONS_TABLE = Object.freeze({ schema: 'drizzle', table: '__drizzle_migrations' });

/** The structured-logger surface the migrator needs (satisfied by `@blackwing/logger`). */
export interface MigrationLogger {
  info(fields: Record<string, unknown>, message: string): void;
}

const journalSchema = z.object({
  entries: z.array(z.object({ idx: z.int().nonnegative(), tag: z.string().min(1) })),
});

/** The migration names in apply order, e.g. `0001_kill_switch`, from the drizzle journal. */
export function migrationNames(): string[] {
  const raw: unknown = JSON.parse(readFileSync(`${MIGRATIONS_DIR}meta/_journal.json`, 'utf8'));
  return journalSchema
    .parse(raw)
    .entries.toSorted((a, b) => a.idx - b.idx)
    .map((entry) => entry.tag);
}

/**
 * Applies every pending migration in one transaction. Call it with a client connected as the owner
 * role (`bw_owner`): migrations never run as the RLS-subject app role (§7). Logs the migration names
 * only (no connection details, no data).
 */
export async function migrateDatabase(
  client: pg.Client | pg.PoolClient,
  logger?: MigrationLogger,
): Promise<void> {
  const migrations = migrationNames();
  logger?.info({ migrations }, 'applying database migrations');
  await migrate(drizzle({ client }), {
    migrationsFolder: MIGRATIONS_DIR,
    migrationsSchema: MIGRATIONS_TABLE.schema,
    migrationsTable: MIGRATIONS_TABLE.table,
  });
  logger?.info({ migrations }, 'database migrations applied');
}
